/*
 * A208336  Triangle of coefficients of polynomials u(n,x) jointly generated
 *          with A208337; see the Formula section.
 * https://oeis.org/A208336
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabl
 * Formula:   a(n) is the coefficient of x^(k-1) in u(r,x) where r is the row
 *            such that r(r-1)/2 < n <= r(r+1)/2 and k = n - r(r-1)/2. The
 *            polynomials are generated by u(1,x)=1, v(1,x)=1,
 *            u(n,x)=u(n-1,x)+x*v(n-1,x), v(n,x)=(x+1)*u(n-1,x)+x*v(n-1,x)
 * Range:     u8 n <= 41, u16 n <= 68, u32 n <= 68, u64 n <= 68, u128 n <= 68,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <math.h>

seq_t a(idx_t n)
{
    if (n == 0) return 0;          /* sequence starts at n=1 */

    /* find the row r by solving r(r+1)/2 >= n */
    idx_t r = (idx_t)((sqrt((long double)(8.0L * n + 1.0L)) - 1.0L) / 2.0L);
    if (r * (r + 1) / 2 < n) ++r;
    while ((r - 1) * r / 2 >= n) --r;

    /* position within the row (1-indexed) */
    idx_t prevTri = (r - 1) * r / 2;
    idx_t pos = n - prevTri;        /* 1 .. r */

    /* allocate coefficient arrays for current row */
    seq_t *u = (seq_t *)calloc(r + 1, sizeof(seq_t));
    seq_t *v = (seq_t *)calloc(r + 1, sizeof(seq_t));
    u[0] = 1;
    v[0] = 1;
    idx_t prevSize = 1;

    for (idx_t row = 2; row <= r; ++row) {
        idx_t newSize = row;
        seq_t *new_u = (seq_t *)calloc(newSize, sizeof(seq_t));
        seq_t *new_v = (seq_t *)calloc(newSize, sizeof(seq_t));

        for (idx_t j = 0; j < newSize; ++j) {
            /* u_n = u_{n-1} + x*v_{n-1} */
            seq_t cu = (j < prevSize) ? u[j] : 0;
            seq_t cv_shift = (j > 0 && j - 1 < prevSize) ? v[j - 1] : 0;
            new_u[j] = cu + cv_shift;

            /* v_n = u_{n-1} + x*u_{n-1} + x*v_{n-1} */
            seq_t cu_shift = (j > 0 && j - 1 < prevSize) ? u[j - 1] : 0;
            seq_t cv_shift2 = (j > 0 && j - 1 < prevSize) ? v[j - 1] : 0;
            new_v[j] = cu + cu_shift + cv_shift2;
        }

        free(u);
        free(v);
        u = new_u;
        v = new_v;
        prevSize = newSize;
    }

    seq_t result = u[pos - 1];

    free(u);
    free(v);
    return result;
}
